settings.cellStyleFunction:
// Color the Debug Message cell red when its text looks like a fault/alert.
try {
    var msg = value;
    var s = String(msg == null ? '' : msg).toLowerCase();
    var hit = s.indexOf('alert') >= 0 || s.indexOf('fail') >= 0 || s.indexOf('reject') >= 0 ||
              s.indexOf('leak') >= 0 || s.indexOf('fault') >= 0 || s.indexOf('overload') >= 0 ||
              s.indexOf('overrun') >= 0 || s.indexOf('dry run') >= 0 ||
              s.indexOf('high voltage') >= 0 || s.indexOf('low voltage') >= 0 ||
              s.indexOf('phase') >= 0;
    if (hit) return { color: '#c62828', fontWeight: 500 };
} catch (_) {}
return {};

settings.rowStyleFunction:
