headerButton.customFunction:
// Access widget context
var data = widgetContext.data; // Timeseries data
var timeWindow = widgetContext.timeWindow; // Time window for start/end time
var http = widgetContext.http;

function formatLocalDate(timestamp) {
    var date = new Date(timestamp);
    var year = date.getFullYear();
    var month = String(date.getMonth() + 1).padStart(2, '0');
    var day = String(date.getDate()).padStart(2, '0');
    var hours = String(date.getHours()).padStart(2, '0');
    var minutes = String(date.getMinutes()).padStart(2, '0');
    var seconds = String(date.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

// Collect unique entities with their IDs
var macIds = [];
var entityInfo = {};
data.forEach(function(ds) {
    var eName = ds.datasource.entityName;
    if (!entityInfo[eName]) {
        macIds.push(eName);
        entityInfo[eName] = {
            entityId: ds.datasource.entityId,
            entityLabel: ds.datasource.entityLabel || eName,
            deviceName: null
        };
    }
});

var startTime = new Date(timeWindow.minTime).toISOString();
var endTime = new Date(timeWindow.maxTime).toISOString();

// Fetch deviceName client attribute for each entity, then generate CSV
var pending = macIds.length;

function onAllResolved() {
    var csvContent = "data:text/csv;charset=utf-8,";

    // Build deviceNameMap: deviceName attribute -> entityLabel -> entityName
    var deviceNameMap = {};
    macIds.forEach(function(eName) {
        var info = entityInfo[eName];
        deviceNameMap[eName] = info.deviceName || info.entityLabel || eName;
    });

    var deviceNames = macIds.map(function(m) { return deviceNameMap[m]; });

    // Add metadata
    csvContent += "Device(s)," + deviceNames.join("; ") + "\n";
    csvContent += "Mac ID(s)," + macIds.join("; ") + "\n";
    csvContent += "Start Time," + startTime + "\n";
    csvContent += "End Time," + endTime + "\n";
    csvContent += "\n";

    // Create CSV headers
    var headers = ["Timestamp"];
    data.forEach(function(ds) {
        var displayName = deviceNameMap[ds.datasource.entityName] || ds.datasource.entityName;
        headers.push(displayName + " - " + ds.dataKey.label);
    });
    csvContent += headers.join(",") + "\n";

    // Process timeseries data
    var rows = {};
    data.forEach(function(ds) {
        var displayName = deviceNameMap[ds.datasource.entityName] || ds.datasource.entityName;
        ds.data.forEach(function(point) {
            var timestamp = point[0];
            var value = point[1];
            if (!rows[timestamp]) {
                rows[timestamp] = { timestamp: formatLocalDate(timestamp), values: {} };
            }
            rows[timestamp].values[displayName + " - " + ds.dataKey.label] = value;
        });
    });

    // Convert rows to CSV
    Object.keys(rows).forEach(function(timestamp) {
        var row = [rows[timestamp].timestamp];
        headers.slice(1).forEach(function(header) {
            row.push(rows[timestamp].values[header] || "");
        });
        csvContent += row.join(",") + "\n";
    });

    // Trigger CSV download
    var encodedUri = encodeURI(csvContent);
    var link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", deviceNames.join("; ") + "_current_voltage_" + startTime.split(" ")[0] + "_" + endTime.split(" ")[0] + ".csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

// Fetch deviceName attribute for each device via API
macIds.forEach(function(eName) {
    var info = entityInfo[eName];
    var url = '/api/plugins/telemetry/DEVICE/' + info.entityId + '/values/attributes/CLIENT_SCOPE?keys=deviceName';
    http.get(url).subscribe(
        function(response) {
            if (response && response.length > 0) {
                response.forEach(function(attr) {
                    if (attr.key === 'deviceName' && attr.value) {
                        info.deviceName = attr.value;
                    }
                });
            }
            pending--;
            if (pending === 0) onAllResolved();
        },
        function(error) {
            pending--;
            if (pending === 0) onAllResolved();
        }
    );
});

// Refresh - re-pull the current timewindow from the server.
try {
    if (widgetContext.subscriptionApi && typeof widgetContext.subscriptionApi.reload === 'function') {
        widgetContext.subscriptionApi.reload();
    } else if (widgetContext.subscription && typeof widgetContext.subscription.update === 'function') {
        widgetContext.subscription.update();
    } else if (widgetContext.subscription && typeof widgetContext.subscription.onUpdated === 'function') {
        widgetContext.subscription.onUpdated();
    } else if (widgetContext.updateTimewindow) {
        widgetContext.updateTimewindow(widgetContext.timeWindow);
    }
    if (widgetContext.detectChanges) widgetContext.detectChanges();
} catch (e) { console.error('Refresh failed', e); }

// Synchronize Logs - ask the device to resend entries in a date range.
// Uses the resendRecentLogs RPC handled by mqttCallback in firmware.
try {
    var data = widgetContext.data || [];
    var entityId = null, entityLabel = null;
    if (data.length && data[0].datasource) {
        entityId = data[0].datasource.entityId;
        entityLabel = data[0].datasource.entityLabel || data[0].datasource.entityName;
    }
    if (!entityId) { window.alert('No device selected in this widget.'); return; }

    function pad(n){ return String(n).padStart(2,'0'); }
    function todayStr(){ var d=new Date(); return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }
    function yestStr(){ var d=new Date(Date.now()-86400000); return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }

    var defFrom = yestStr();
    var defTo   = todayStr();
    var fromStr = window.prompt('Synchronize Debug Logs - From date (YYYY-MM-DD)\nDevice: ' + (entityLabel||entityId), defFrom);
    if (!fromStr) return;
    var toStr   = window.prompt('Synchronize Debug Logs - To date (YYYY-MM-DD)', defTo);
    if (!toStr) return;

    var fp = fromStr.split('-'), tp = toStr.split('-');
    if (fp.length!==3 || tp.length!==3) { window.alert('Dates must be in YYYY-MM-DD format.'); return; }
    var fromMs = new Date(+fp[0], +fp[1]-1, +fp[2], 0, 0, 0).getTime();
    var toMs   = new Date(+tp[0], +tp[1]-1, +tp[2], 23, 59, 59).getTime();
    if (isNaN(fromMs) || isNaN(toMs)) { window.alert('Invalid date.'); return; }
    if (fromMs > toMs) { window.alert('"From" must be on or before "To".'); return; }

    var http = widgetContext.http;
    if (!http) { window.alert('HTTP service unavailable in this widget.'); return; }
    http.post('/api/rpc/twoway/' + entityId, {
        method: 'resendRecentLogs',
        params: { from: Math.floor(fromMs/1000), to: Math.floor(toMs/1000), type: 'debug' },
        timeout: 10000
    }).subscribe(function(r){
        var resp = (r && r.data) ? r.data : r;
        if (resp && resp.success) {
            var n = resp.queued || 0;
            if (widgetContext.showSuccessToast) widgetContext.showSuccessToast('Queued ' + n + ' entries. Refreshing...', 3000, 'bottom', 'left', 'successToast');
            else window.alert('Queued ' + n + ' entries on device.');
            // Kick a few reloads so the backfilled rows appear without a manual refresh.
            [4000, 12000, 30000].forEach(function(t){
                setTimeout(function(){
                    try {
                        if (widgetContext.subscriptionApi && widgetContext.subscriptionApi.reload) widgetContext.subscriptionApi.reload();
                        else if (widgetContext.subscription && widgetContext.subscription.update) widgetContext.subscription.update();
                    } catch(_){}
                }, t);
            });
        } else {
            var msg = (resp && resp.message) ? resp.message : 'Device busy or not connected';
            if (widgetContext.showErrorToast) widgetContext.showErrorToast(msg, 'bottom', 'left', 'errorToast');
            else window.alert(msg);
        }
    }, function(err){
        var msg = 'Request failed (device offline?)';
        if (widgetContext.showErrorToast) widgetContext.showErrorToast(msg, 'bottom', 'left', 'errorToast');
        else window.alert(msg);
    });
} catch (e) { console.error('Synchronize Logs failed', e); window.alert('Synchronize Logs failed: ' + e.message); }

config.widgetCss:
/* Let the time-window picker float to the top-right of the widget frame.
   Works on TB versions that render <tb-timewindow> at the widget root. */
tb-timewindow,
.tb-timewindow,
tb-timewindow-panel,
.tb-timewindow-panel {
  position: absolute;
  top: 6px;
  right: 10px;
  z-index: 5;
  margin: 0 !important;
}

/* Give the title enough room so the absolutely-positioned picker never
   overlaps it on narrow widget sizes. */
.tb-widget-title,
.tb-widget-title-container,
mat-card-title {
  padding-right: 190px !important;
}

/* Fallback: if the picker stays in normal flow on this TB build, at least
   give it some breathing room. */
.tb-widget-timewindow,
.tb-legend-timewindow,
.tb-widget-timewindow-container {
  margin: 6px 8px 10px auto !important;
  padding: 2px 6px !important;
  display: inline-flex !important;
  justify-content: flex-end !important;
}

/* Allow row-level colour (set by rowStyleFunction) to reach every cell. */
.mat-mdc-row .mat-mdc-cell,
.mat-row .mat-cell,
tr .mat-cell {
    color: inherit !important;
}
